<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';require_permission('services.manage');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);if($action==='delete'){$pdo->prepare('DELETE FROM services WHERE id=?')->execute([$id]);flash('success','Servicio eliminado.');}else{$title=trim((string)($_POST['title']??''));if($title==='')throw new RuntimeException('Escribe el nombre del servicio.');$data=[$title,rich_text_sanitize((string)($_POST['description']??'')),trim((string)($_POST['icon']??'✦')),(int)($_POST['sort_order']??0),isset($_POST['active'])?1:0];if($id){$data[]=$id;$pdo->prepare('UPDATE services SET title=?,description=?,icon=?,sort_order=?,active=? WHERE id=?')->execute($data);}else{$pdo->prepare('INSERT INTO services(title,description,icon,sort_order,active) VALUES(?,?,?,?,?)')->execute($data);}flash('success','Servicio guardado.');}header('Location: services.php');exit;}catch(Throwable $e){flash('error',$e->getMessage());header('Location: services.php');exit;}}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM services WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT * FROM services ORDER BY sort_order,id')->fetchAll();$pageTitle='Services';$active='services';require __DIR__.'/_header.php';?>
<div class="page-heading"><div><p class="eyebrow">CATÁLOGO</p><h1>Servicios</h1><p class="muted">Administra lo que Sabrosísimo Mix ofrece en eventos.</p></div></div><section class="panel"><h2><?=$edit?'Editar servicio':'Agregar servicio'?></h2><form class="crud-form" method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($edit['id']??0)?>"><label>Nombre<input name="title" value="<?=h($edit['title']??'')?>" required></label><label>Ícono o emoji<input name="icon" value="<?=h($edit['icon']??'✦')?>"></label><label class="full">Descripción<textarea name="description"><?=h($edit['description']??'')?></textarea></label><label>Orden<input type="number" name="sort_order" value="<?=h($edit['sort_order']??0)?>"></label><label class="status-field"><span class="field-label">Estado</span><span class="check-control"><input type="checkbox" name="active" value="1" <?=!$edit||(int)$edit['active']===1?'checked':''?>><span>Activo</span></span></label><div class="full form-actions"><button>Guardar</button><?php if($edit):?><a class="button secondary" href="services.php">Cancelar</a><?php endif;?></div></form></section><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Orden</th><th>Servicio</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['sort_order']?></td><td><strong><?=h($r['icon'])?> <?=h($r['title'])?></strong><br><small><?=h(rich_text_plain((string)$r['description']))?></small></td><td><span class="badge <?=$r['active']?'active':''?>"><?=$r['active']?'Activo':'Oculto'?></span></td><td><div class="actions"><a class="button secondary small" href="?edit=<?=$r['id']?>">Editar</a><form method="post" data-premium-confirm data-confirm-title="Eliminar servicio" data-confirm-message="¿Eliminar este servicio? Esta acción no se puede deshacer." data-confirm-ok="Sí, eliminar" data-confirm-cancel="Cancelar"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger small">Eliminar</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>
